DROP TABLE IF EXISTS `wordpress_import_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wordpress_import_batches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `file_path` varchar(255) NOT NULL,
  `original_file_name` varchar(255) NOT NULL,
  `old_domain` varchar(255) NOT NULL,
  `media_mode` varchar(255) NOT NULL,
  `local_media_base_path` varchar(255) DEFAULT NULL,
  `import_post_types` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`import_post_types`)),
  `import_statuses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`import_statuses`)),
  `duplicate_mode` varchar(255) NOT NULL,
  `dry_run` tinyint(1) NOT NULL DEFAULT 0,
  `limit` int(11) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `total_items` int(11) NOT NULL DEFAULT 0,
  `processed_items` int(11) NOT NULL DEFAULT 0,
  `imported_items` int(11) NOT NULL DEFAULT 0,
  `updated_items` int(11) NOT NULL DEFAULT 0,
  `skipped_items` int(11) NOT NULL DEFAULT 0,
  `failed_items` int(11) NOT NULL DEFAULT 0,
  `missing_media_items` int(11) NOT NULL DEFAULT 0,
  `started_at` timestamp NULL DEFAULT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  `error_message` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `wordpress_import_batches_created_by_foreign` (`created_by`),
  CONSTRAINT `wordpress_import_batches_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
